messages.content:
Tool response:
Tool: create_donation
Description: Create Donation
Parameters:
    {
      "type": "object",
      "properties": {
        "constituent_id": {
          "type": "string",
          "title": "Constituent Id"
        },
        "amount": {
          "type": "number",
          "title": "Amount"
        },
        "donation_date": {
          "type": "string",
          "format": "date",
          "title": "Donation Date"
        },
        "campaign_id": {
          "type": "integer",
          "title": "Campaign Id"
        },
        "fund_id": {
          "type": "integer",
          "title": "Fund Id"
        },
        "appeal_id": {
          "type": "integer",
          "title": "Appeal Id"
        },
        "payment_method_id": {
          "type": "integer",
          "title": "Payment Method Id"
        },
        "status": {
          "type": "string",
          "enum": [
            "Pending",
            "Processed",
            "Failed",
            "Refunded"
          ],
          "title": "Status"
        },
        "receipt_date": {
          "type": "string",
          "format": "date",
          "title": "Receipt Date"
        }
      },
      "required": [
        "constituent_id",
        "amount",
        "donation_date",
        "campaign_id",
        "fund_id",
        "appeal_id",
        "payment_method_id",
        "status",
        "receipt_date"
      ]
    }
